/**
 * High-craft Kanri Intro Logo component inspired by ChapterPlayer.
 *
 * Sequence:
 * 1. Mark lands large (scale 2.0 -> 1.0) with exponential ease and settles.
 * 2. Settles into the lockup position as the signature Panchang wordmark letters
 *    (K - A - N - R - I) emerge in crisp sequence.
 * 3. Tagline fades and reveals smoothly.
 */
@Composable
fun KanriIntroLogo(
    isLight: Boolean,
    modifier: Modifier = Modifier
) {
    val markPath = remember {
        try {
            PathParser.createPathFromPathData(MARK_PATH_DATA).asComposePath()
        } catch (_: Exception) {
            Path()
        }
    }

    val letterPaths = remember {
        listOf(PATH_K, PATH_A, PATH_N, PATH_R, PATH_I).map {
            PathParser.createPathFromPathData(it).asComposePath()
        }
    }

    val markScale = remember { Animatable(2.2f) }
    val markAlpha = remember { Animatable(0f) }
    val markOffsetY = remember { Animatable(-32f) }

    val letterOffsets = remember { List(5) { Animatable(18f) } }
    val letterAlphas = remember { List(5) { Animatable(0f) } }

    val taglineAlpha = remember { Animatable(0f) }
    val taglineOffsetY = remember { Animatable(12f) }

    LaunchedEffect(Unit) {
        // Step 1: Mark lands large with exponential ease (0 to 600ms)
        launch {
            markAlpha.animateTo(1f, tween(400, easing = LinearEasing))
        }
        launch {
            markScale.animateTo(1f, tween(650, easing = EaseDecel))
        }
        launch {
            markOffsetY.animateTo(0f, tween(650, easing = EaseDecel))
        }

        // Step 2: Staggered Panchang Letters rise and sharpen (from 450ms)
        delay(350L)
        letterPaths.indices.forEach { index ->
            launch {
                delay(index * 75L)
                launch {
                    letterAlphas[index].animateTo(1f, tween(360, easing = LinearEasing))
                }
                launch {
                    letterOffsets[index].animateTo(0f, tween(420, easing = EaseDecel))
                }
            }
        }

        // Step 3: Tagline reveal (at 1000ms)
        delay(600L)
        launch {
            taglineAlpha.animateTo(1f, tween(450, easing = FastOutSlowInEasing))
        }
        launch {
            taglineOffsetY.animateTo(0f, tween(450, easing = EaseDecel))
        }
    }

    val infiniteTransition = rememberInfiniteTransition(label = "logo_sheen")
    val sheenProgress by infiniteTransition.animateFloat(
        initialValue = -150f,
        targetValue = 600f,
        animationSpec = infiniteRepeatable(
            animation = tween(4000, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = "sheen_anim"
    )

    val inkColor = if (isLight) Color(0xFF1E2229) else Color(0xFFF7F5F0)
    val accentRed = Color(0xFFC43B38) // Cinnabar red accent from Shan Shui

    Column(
        modifier = modifier.fillMaxWidth(),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        // Combined Emblem Mark + KANRI Wordmark Canvas
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .height(84.dp),
            contentAlignment = Alignment.Center
        ) {
            Canvas(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(84.dp)
            ) {
                val canvasW = size.width
                val canvasH = size.height

                // Draw centered lockup: Emblem on left + Panchang KANRI wordmark on right
                val desiredMarkH = 46.dp.toPx()
                val desiredMarkW = (MARK_WIDTH / MARK_HEIGHT) * desiredMarkH

                val desiredWordH = 34.dp.toPx()
                val desiredWordW = (SVG_TOTAL_WIDTH / SVG_TOTAL_HEIGHT) * desiredWordH
                val gap = 16.dp.toPx()
                val totalLockupW = desiredMarkW + gap + desiredWordW

                val startX = (canvasW - totalLockupW) / 2f
                val centerY = canvasH / 2f

                // 1. Draw Monogram Emblem Mark
                val markCurrentScale = markScale.value
                val markCurrentAlpha = markAlpha.value
                val markCurrentY = markOffsetY.value.dp.toPx()

                if (markCurrentAlpha > 0.01f) {
                    val mCenterX = startX + desiredMarkW / 2f
                    val mCenterY = centerY + markCurrentY

                    scale(
                        scale = markCurrentScale,
                        pivot = Offset(mCenterX, mCenterY)
                    ) {
                        translate(
                            left = startX - MARK_MIN_X * (desiredMarkW / MARK_WIDTH),
                            top = centerY - (desiredMarkH / 2f) - MARK_MIN_Y * (desiredMarkH / MARK_HEIGHT) + markCurrentY
                        ) {
                            scale(
                                scaleX = desiredMarkW / MARK_WIDTH,
                                scaleY = desiredMarkH / MARK_HEIGHT,
                                pivot = Offset.Zero
                            ) {
                                drawPath(
                                    path = markPath,
                                    color = accentRed.copy(alpha = markCurrentAlpha)
                                )
                            }
                        }
                    }
                }

                // 2. Draw KANRI letters with individual staggered rise & alpha
                val wordStartX = startX + desiredMarkW + gap
                val wordScaleX = desiredWordW / SVG_TOTAL_WIDTH
                val wordScaleY = desiredWordH / SVG_TOTAL_HEIGHT

                letterPaths.forEachIndexed { i, path ->
                    val alpha = letterAlphas[i].value
                    val offY = letterOffsets[i].value.dp.toPx()
                    if (alpha > 0.01f) {
                        val sliceMinX = SLICE_BOUNDS_X[i * 2]
                        val sliceMaxX = SLICE_BOUNDS_X[i * 2 + 1]

                        val clipLeft = wordStartX + (sliceMinX - SVG_TOTAL_MIN_X) * wordScaleX
                        val clipRight = wordStartX + (sliceMaxX - SVG_TOTAL_MIN_X) * wordScaleX
                        val clipTop = centerY - (desiredWordH / 2f) - 20f
                        val clipBottom = centerY + (desiredWordH / 2f) + 20f

                        clipRect(
                            left = clipLeft - 1f,
                            top = clipTop,
                            right = clipRight + 1f,
                            bottom = clipBottom
                        ) {
                            translate(
                                left = wordStartX - SVG_TOTAL_MIN_X * wordScaleX,
                                top = centerY - (desiredWordH / 2f) - SVG_TOTAL_MIN_Y * wordScaleY + offY
                            ) {
                                scale(
                                    scaleX = wordScaleX,
                                    scaleY = wordScaleY,
                                    pivot = Offset.Zero
                                ) {
                                    drawPath(
                                        path = path,
                                        color = inkColor.copy(alpha = alpha)
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }

        Spacer(modifier = Modifier.height(10.dp))

        // Tagline Reveal
        Column(
            modifier = Modifier
                .graphicsLayer {
                    alpha = taglineAlpha.value
                    translationY = taglineOffsetY.value.dp.toPx()
                },
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            Text(
                text = "FINANCIAL SERENITY",
                fontFamily = Panchang,
                fontWeight = FontWeight.SemiBold,
                fontSize = 11.5.sp,
                letterSpacing = 3.2.sp,
                color = accentRed.copy(alpha = 0.90f),
                textAlign = TextAlign.Center
            )

            Spacer(modifier = Modifier.height(3.dp))

            Text(
                text = "Know where every rupee went.",
                fontFamily = GoogleSansFlex,
                fontWeight = FontWeight.Normal,
                fontSize = 13.5.sp,
                letterSpacing = 0.4.sp,
                color = inkColor.copy(alpha = 0.65f),
                textAlign = TextAlign.Center
            )
        }
    }
}

